# canonical unit per (metric) — series must not mix
CANON = {
    "condition_good_excellent": "%", "abandonment_rate": "%",
    "rainfall_pct_normal": "% of normal", "forecast_rainfall_pct": "% of LPA",
    "crop_damage_pct": "%", "reservoir_fill": "%", "grain_moisture": "%",
}
PUB_ROOT = lambda p: re.split(r"[/(]", p)[0].strip()

def norm_region(s):
    s = (s or "").lower()
    s = re.split(r"[;(,]", s)[0].strip()
    return re.sub(r"\s+", " ", s)

def series_key(r):
    # region MUST be part of the key: national and sub-national readings of the same
    # metric are different series, and two farms are not a time series at all.
    return f"{r.get('country') or 'GLOBAL'}|{norm_region(r.get('region'))}|{r['crop']}|{r.get('metric_name') or 'na'}|{PUB_ROOT(r['publisher'])}"

def claim_key(r):
    return f"{r.get('country') or 'GLOBAL'}|{r['crop']}|{r.get('season','')}|{r.get('metric_name') or 'na'}|{r.get('metric_value')}|{r.get('direction')}"

