for r in june:
    r["crop"] = CROP_MAP.get(r["crop"], r["crop"])
    if r.get("metric_name"):
        r["metric_name"] = METRIC_MAP.get(r["metric_name"], r["metric_name"])
        if r["metric_name"] in CANON: r["metric_unit"] = CANON[r["metric_name"]]
    if r["id"] in JUNE_EVENT: r["event_date"] = JUNE_EVENT[r["id"]]
    r["month"] = "2026-06"

# ---------------------------------------------------------------- July / August
def R(cid,country,region,crop,season,hz,ic,qt,metric,val,unit,dirn,base,ev,title,url,pub,pd,quote,attr,corr=0,comp=None,flag=None):
    return {"id":cid,"country":country,"region":region,"crop":crop,"season":season,
            "hazard_type":hz,"impact_class":ic,"is_quantified":qt,"metric_name":metric,
            "metric_value":val,"metric_unit":CANON.get(metric,unit),"direction":dirn,"baseline":base,
            "event_date":ev,"title":title,"url":url,"publisher":pub,"published_date":pd,
            "verbatim_quote":quote,"attribution":attr,"corroboration_count":corr or 1,
            "companies":comp or [],"review_flag":flag,"corroborations":[],
            "summary":title}

