for r in JUL: r["month"] = "2026-07"
for r in AUG: r["month"] = "2026-08"

rows = june + JUL + AUG

# ---------------------------------------------------------------- finalise
seen_claims = {}
for r in rows:
    r.setdefault("companies", [])
    r.setdefault("corroborations", [])
    r.setdefault("review_flag", None)
    if "source_badge" not in r:
        b, f = badge(r["url"], r["publisher"])
        r["source_badge"] = b
        if f and not r["review_flag"]: r["review_flag"] = f
    r["series_key"] = series_key(r)
    r["claim_key"] = claim_key(r)
    seen_claims.setdefault(r["claim_key"], r["id"])

by_month = collections.defaultdict(list)
for r in rows: by_month[r["month"]].append(r)
for m, rs in by_month.items():
    json.dump(rs, open(f"corpus/{m}.json", "w"), indent=1, ensure_ascii=False)

# series index — only series with >1 reading are chartable
series = collections.defaultdict(list)
for r in rows:
    if r["is_quantified"] and isinstance(r.get("metric_value"), (int, float)):
        series[r["series_key"]].append({"id": r["id"], "event_date": r.get("event_date"),
                                        "value": r["metric_value"], "unit": r["metric_unit"],
                                        "month": r["month"]})
chartable = {k: sorted(v, key=lambda x: x["event_date"] or "") for k, v in series.items() if len(v) > 1}
json.dump(chartable, open("index/series_index.json", "w"), indent=1)
json.dump({r["claim_key"]: {"id": r["id"], "corroboration_count": r.get("corroboration_count", 1)} for r in rows},
          open("index/claims_index.json", "w"), indent=1)
json.dump(rows, open("corpus/all.json", "w"), indent=1, ensure_ascii=False)

print("TOTAL ROWS:", len(rows))
for m in sorted(by_month): print(" ", m, len(by_month[m]))
print("quantified:", sum(1 for r in rows if r["is_quantified"]))
print("distinct series:", len(series), "| chartable (>1 reading):", len(chartable))
print("badges:", dict(collections.Counter(r["source_badge"] for r in rows)))
print("hazards:", dict(collections.Counter(r["hazard_type"] for r in rows)))
print("attribution:", dict(collections.Counter(r["attribution"] for r in rows)))
print("positive (up):", sum(1 for r in rows if r.get("direction") == "up"))
print("flagged:", sum(1 for r in rows if r.get("review_flag")))
print("\nTOP CHARTABLE SERIES:")
for k, v in sorted(chartable.items(), key=lambda x: -len(x[1]))[:14]:
    print(f"  {len(v)}x  {k}  ->  {[x['value'] for x in v]}")
missing = [r["id"] for r in rows if r["is_quantified"] and not r.get("verbatim_quote")]
print("\nquantified WITHOUT quote:", missing)
noev = [r["id"] for r in rows if r["is_quantified"] and not r.get("event_date")]
print("quantified WITHOUT event_date:", noev)
